import sys, re, itertools

def parse_grammar(text):
    # split on "::=" boundaries: find tokens like X::=rhs
    parts = re.findall(r'([A-Z])\s*::=\s*([^\s]+(?:\s*)?)', text)
    # safer: split text by whitespace-collapsing then regex
    txt = re.sub(r'\s+', ' ', text).strip()
    # find all occurrences of "L::=" and slice
    idx = [(m.start(), m.group(1)) for m in re.finditer(r'([A-Za-z])::=', txt)]
    rules = []
    for i,(pos,left) in enumerate(idx):
        end = idx[i+1][0] if i+1 < len(idx) else len(txt)
        rhs = txt[pos+len(left)+3:end].strip()
        alts = [a.strip() for a in rhs.split('|')]
        rules.append((left, alts))
    return rules

def analyze(text, name):
    rules = parse_grammar(text)
    nts = [l for l,_ in rules]
    prods = {}
    order = []
    for l,alts in rules:
        prods.setdefault(l, [])
        for a in alts:
            prods[l].append(a)
            order.append((l,a))
    NT = set(nts)
    T = set()
    for l,a in order:
        for ch in a:
            if ch not in NT and ch != '@':
                T.add(ch)
    start = nts[0]

    EPS='@'
    FIRST = {A:set() for A in NT}
    for t in T: FIRST[t]={t}
    def first_str(s):
        out=set()
        if s==EPS or s=='':
            return {EPS}
        for ch in s:
            f = FIRST[ch] if ch in FIRST else {ch}
            out |= (f - {EPS})
            if EPS not in f:
                return out
        out.add(EPS)
        return out
    changed=True
    while changed:
        changed=False
        for A,a in order:
            new = first_str(a)
            if not new <= FIRST[A]:
                FIRST[A] |= new; changed=True

    FOLLOW={A:set() for A in NT}
    FOLLOW[start].add('#')
    changed=True
    while changed:
        changed=False
        for A,a in order:
            if a==EPS: continue
            for i,ch in enumerate(a):
                if ch in NT:
                    rest = a[i+1:]
                    f = first_str(rest) if rest else {EPS}
                    add = (f-{EPS})
                    if EPS in f: add |= FOLLOW[A]
                    if not add <= FOLLOW[ch]:
                        FOLLOW[ch] |= add; changed=True

    # table
    table={}
    conflicts=[]
    for A,a in order:
        f=first_str(a)
        for t in (f-{EPS}):
            if (A,t) in table and table[(A,t)]!=a: conflicts.append((A,t,table[(A,t)],a))
            table[(A,t)]=a
        if EPS in f:
            for t in FOLLOW[A]:
                if (A,t) in table and table[(A,t)]!=a: conflicts.append((A,t,table[(A,t)],a))
                table[(A,t)]=a
    return dict(rules=order, NT=NT, T=T, start=start, FIRST=FIRST, FOLLOW=FOLLOW,
                table=table, conflicts=conflicts, first_str=first_str, name=name)

def trace(G, s):
    stack=['#', G['start']]
    inp=list(s)+['#']
    rows=[]
    i=0
    step=0
    while True:
        step+=1
        if step>200: rows.append(('LOOP','','')); return rows,'LOOP'
        st=''.join(stack); rem=''.join(inp[i:])
        top=stack[-1]; la=inp[i]
        if top=='#' and la=='#':
            rows.append((st,rem,'accept')); return rows,'ACCEPT'
        if top=='#':
            rows.append((st,rem,'ERROR: stack exhausted (top #) input left')); return rows,'REJECT'
        if top in G['NT']:
            a=G['table'].get((top,la))
            if a is None:
                rows.append((st,rem,'ERROR: M[%s,%s] empty'%(top,la))); return rows,'REJECT'
            rows.append((st,rem,'%s::=%s'%(top,a)))
            stack.pop()
            if a!='@':
                for ch in reversed(a): stack.append(ch)
        else:
            if top==la:
                rows.append((st,rem,'match %s'%top)); stack.pop(); i+=1
            else:
                rows.append((st,rem,'ERROR: mismatch stack top %s vs input %s'%(top,la))); return rows,'REJECT'

def show(G):
    print('=== %s ==='%G['name'])
    print('rules:', G['rules'])
    print('start:', G['start'], 'NT:', sorted(G['NT']), 'T:', sorted(G['T']))
    for A in sorted(G['NT']): print('  FIRST(%s)=%s'%(A, sorted(G['FIRST'][A])))
    for A in sorted(G['NT']): print('  FOLLOW(%s)=%s'%(A, sorted(G['FOLLOW'][A])))
    print('  conflicts:', G['conflicts'])
    cols=sorted(G['T'])+['#']
    print('  table:')
    for A in sorted(G['NT']):
        print('    %s: '%A + ' | '.join('%s->%s'%(t, G['table'].get((A,t),'')) for t in cols if (A,t) in G['table']))

if __name__=='__main__':
