import re, itertools
from collections import deque

def parse_grammar(text):
    txt = re.sub(r'\s+',' ',text).strip()
    idx=[(m.start(), m.group(1)) for m in re.finditer(r'([A-Za-z])::=', txt)]
    prods={}; order=[]
    for i,(pos,left) in enumerate(idx):
        end = idx[i+1][0] if i+1<len(idx) else len(txt)
        rhs = txt[pos+len(left)+3:end].strip()
        for a in rhs.split('|'):
            a=a.strip()
            prods.setdefault(left,[]).append('' if a=='@' else a)
            order.append((left,a))
    start=idx[0][1]
    return prods,start,order

# Earley recognizer (grammar-agnostic, handles nullables) -- independent of LL(1)
def earley(prods, start, s):
    NT=set(prods)
    S='$'
    P=dict(prods); P[S]=[start]
    chart=[set() for _ in range(len(s)+1)]
    chart[0].add((S,P[S][0],0,0))
    for i in range(len(s)+1):
        added=True
        while added:
            added=False
            for item in list(chart[i]):
                A,rhs,dot,j=item
                if dot<len(rhs):
                    X=rhs[dot]
                    if X in NT:
                        for r in P[X]:
                            it=(X,r,0,i)
                            if it not in chart[i]: chart[i].add(it); added=True
                    else:
                        if i<len(s) and s[i]==X:
                            chart[i+1].add((A,rhs,dot+1,j))
                else:
                    for it2 in list(chart[j]):
                        B,r2,d2,k=it2
                        if d2<len(r2) and r2[d2]==A:
                            it=(B,r2,d2+1,k)
                            if it not in chart[i]: chart[i].add(it); added=True
    return (S,P[S][0],len(P[S][0]),0) in chart[len(s)]

# brute-force leftmost derivation BFS to enumerate short strings
def enumerate_lang(prods,start,maxlen=7,limit=4000):
    NT=set(prods); out=set(); seen={start}; q=deque([start]); n=0
    while q and n<300000:
        n+=1
        form=q.popleft()
        # count terminals
        term=''.join(c for c in form if c not in NT)
        if len(term)>maxlen: continue
        i=next((k for k,c in enumerate(form) if c in NT), None)
        if i is None:
            out.add(form); continue
        A=form[i]
        for r in prods[A]:
            nf=form[:i]+r+form[i+1:]
            if len(nf)>maxlen+6: continue
            if nf not in seen:
                seen.add(nf); q.append(nf)
    return {w for w in out if len(w)<=maxlen}

